const s = new WebSocket(process.env.SMOKE_WS); const timer=setTimeout(()=>process.exit(1),5000); s.onopen=()=>s.send(JSON.stringify({id:1,method:"Runtime.evaluate",params:{expression:"Boolean(document.querySelector(\u0027#root button\u0027))",returnByValue:true}})); s.onmessage=({data})=>{const m=JSON.parse(data);if(m.id===1){clearTimeout(timer);s.close();process.exit(m.result?.result?.value===true?0:1)}}; s.onerror=()=>process.exit(1)
